{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Separation is uneven across datasets: Electronics is weakest, with 14.95% wrong rankings and a negative 10th-percentile margin; Movies_and_TV is strongest, with only 3.03% wrong rankings.",
    "Embedding similarity scores span 0.5392–0.5566, close to the mapped zero-cosine baseline of 0.5; these measurements do not indicate severe directional collapse."
  ],
  "key_implications": [
    "Electronics has the greatest difficulty distinguishing positive items from sampled negatives, while Industrial_and_Scientific and CDs_and_Vinyl also retain weak-margin cases.",
    "Positive mean margins across all datasets show learned separation, but conceal errors in the lower-margin tail.",
    "These sampled-position diagnostics alone do not establish validation HR@10 performance."
  ],
  "evidence": {
    "headline_metrics": {
      "Electronics:pos_neg_margin_p10": -0.4812,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.1495,
      "Electronics:pos_neg_small_margin_rate": 0.2115,
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": 0.0303,
      "Industrial_and_Scientific:pos_neg_small_margin_rate": 0.1183,
      "CDs_and_Vinyl:pos_neg_small_margin_rate": 0.1383
    },
    "brief_metric_read": {
      "Electronics:pos_neg_margin_p10": "Lower-tail margins favor negatives.",
      "Electronics:pos_neg_small_margin_rate": "21.15% of valid positions have margins below 0.5.",
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": "Lowest observed ranking-error rate."
    }
  }
}
